#define REP(i,j) for(int i=0;i<j;i++)

int main() {
    int n, S;
    while(scanf("%d %d", &n, &S), n) {
        int r[10000];
        REP(i, n) {
            scanf("%d", &r[i]);
        }

        // Sort only once at the start
        std::sort(r, r+n);

        int res = 0;
        // Use a single loop to calculate the result
        for(int i=0; i<n; i++) {
            int target = S - r[i];
            // Use binary search to find the first element greater than target
            auto it = std::upper_bound(r+i+1, r+n, target);
            res += std::distance(it, r+n);
        }
        printf("%d\n", res);
    }
}

